window.specNoLatticeEn = {"champ":"The state is a 2×2 matrix over F_p and the operations are big-integer modular multiplication and inversion: there is no lane array and no bit-level operator acting cell by cell; diffusion is only implicit in multiplication and reduction mod p."};
